contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt to Put with a chosen lock time and amount
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");

        // Observe holder balance before
        (uint beforeBalance,) = getHolder(msg.sender);
        uint contractBalanceBefore = address(c).balance;

        // Perform the call: use Put with value `amount`. We must call as this contract is the msg.sender for c.
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        (uint afterBalance,) = getHolder(msg.sender);
        uint contractBalanceAfter = address(c).balance;

        // If the call did not revert then the holder's balance should have increased by amount
        // and the contract's Ether balance should have increased by amount.
        assert(reverted || (afterBalance == beforeBalance + amount && contractBalanceAfter == contractBalanceBefore + amount));
    }

    // helper to call the public getter Acc(address) which returns Holder (unlockTime,balance)
    // The mapping is public, so solidity generates a getter: function Acc(address) public view returns (uint unlockTime, uint balance);
    function getHolder(address who) internal view returns (uint balance, uint unlockTime) {
        // Note: the auto-generated getter for struct returns (uint,uint) in the order of struct fields (unlockTime,balance)
        (uint unlock, uint bal) = c.Acc(who);
        return (bal, unlock);
    }

    // receive to accept refunds if any
    receive() external payable {}
}

