    // We assert: if Collect does not revert then the recorded unlockTime for this caller is strictly less than current block.timestamp.
    function run(uint preFund, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= preFund);

        // Attempt to put funds to c (may revert). Use try/catch to continue.
        bool putReverted;
        try c.Put{value: preFund}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe holder state before Collect
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));

        // Try Collect and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read holder state after Collect
        (uint unlockAfter, uint balAfter) = c.Acc(address(this));

        // If Collect succeeded, it must be that block.timestamp > unlockTime at the time of the call.
        // We cannot read the historical block.timestamp inside c at call time, but since this transaction's
        // block.timestamp is the same for all internal calls, comparing to the observed unlockAfter is valid.
