    // We will: 1) fund the contract c via Put with some amount preFund (may revert),
    // 2) record balances before Collect, 3) try Collect(collectAmount), record whether it reverted,
    // 4) read balances after and assert the general invariant.
    function run(uint preFund, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= preFund);

        // Try to add funds to c for this test contract's Holder (may revert)
        bool putReverted;
        try c.Put{value: preFund}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Observe c's observable state before Collect
        (uint unlockBefore, uint balBefore) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after-state
        (uint unlockAfter, uint balAfter) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // Assertion: If Collect succeeded then contract balance decreased by exactly collectAmount
        // and the recorded holder balance did not decrease by more than the contract's decrease
        // (i.e., holder balance decreases by at most the Ether actually sent out), and holder balance decreased by at least the Ether sent.
        // Since we cannot observe the internal transfer amount directly, we require that if Collect succeeded:
        //   cBalBefore == cBalAfter + collectAmount
        // and
        //   balBefore >= balAfter  (no increase) and balBefore - balAfter <= collectAmount
        // combined gives that holder's recorded decrease is between 0 and collectAmount, and contract's Ether moved exactly collectAmount.
