            cBalBefore == cBalAfter + collectAmount
            && balBefore >= balAfter
            && balBefore - balAfter <= collectAmount
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters to exercise Put and Collect
    // amountPut: Ether to send to Put; lockTime: parameter for Put; collectAmt: requested Collect amount
    function run(uint amountPut, uint lockTime, uint collectAmt) public payable {
        require(address(this).balance >= amountPut, "insufficient balance for put");

        // Read before-values
        uint before_contract_balance = address(c).balance;
        (uint before_unlockTime, uint before_balance) = getAcc(address(this));

        // Call Put by sending Ether and making the call (use fallback via low-level call to exercise fallback path when lockTime == 0)
        // Here we call Put explicitly to set unlockTime; fallback also calls Put(0) but we exercise Put directly.
        c.Put{value: amountPut}(lockTime);

        // Read after Put values
        uint after_contract_balance = address(c).balance;
        (uint after_unlockTime, uint after_balance) = getAcc(address(this));

        // The contract's balance must have increased by exactly amountPut
        bool contract_balance_increased = (after_contract_balance == before_contract_balance + amountPut);

        // The recorded balance for this address must have increased by at least amountPut (sGuard add prevents overflow-induced decrease)
        bool recorded_balance_increased = (after_balance >= before_balance);
        bool recorded_balance_delta_ok = (after_balance - before_balance == amountPut);

        // Now attempt Collect for collectAmt and record whether it reverts
        bool reverted;
        try c.Collect{value: 0}(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After Collect (whether reverted or not), the recorded balance cannot become negative and cannot decrease below zero.
        (uint final_unlockTime, uint final_balance) = getAcc(address(this));
        uint contract_balance_after_collect = address(c).balance;

        // The Collect call, if it succeeded (not reverted), must have sent at most the balance that was available before the Collect
        // We observe this by ensuring that the decrease in c's ether balance is <= the before-Collect recorded balance
        // Let beforeCollectContractBalance = after_contract_balance
        uint beforeCollectContractBalance = after_contract_balance;
        uint contract_balance_decrease = 0;
        if (beforeCollectContractBalance > contract_balance_after_collect) {
            contract_balance_decrease = beforeCollectContractBalance - contract_balance_after_collect;
        }

        // If Collect succeeded then contract_balance_decrease <= after_balance (the recorded balance before Collect)
        bool collect_sent_leq_recorded = reverted || (contract_balance_decrease <= after_balance);

        // Final assert: Put increased contract balance by amountPut and increased recorded balance by amountPut;
        // and Collect, if succeeded, transferred at most the recorded balance present before the Collect.
        assert(contract_balance_increased && recorded_balance_delta_ok && collect_sent_leq_recorded);
    }

    // helper to read Acc public mapping via the autogenerated getter: Acc(address) returns (uint unlockTime, uint balance)
    function getAcc(address a) internal returns (uint, uint) {
        // The getter is a public function; call it and return results
        (uint t, uint b) = c.Acc(a);
        return (t, b);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing Put then Collect and asserting the invariant
    // amountPut: Ether to send to Put; lockTime: parameter for Put; collectAmt: requested Collect amount
    function run(uint amountPut, uint lockTime, uint collectAmt) public payable {
        // ensure this test contract has enough Ether to send for Put
        require(address(this).balance >= amountPut);

        // Read before-values via public getters
        uint before_contract_balance = address(c).balance;
        (uint before_unlockTime, uint before_recorded_balance) = c.Acc(address(this));

        // Call Put sending Ether; top-level state-changing call
        c.Put{value: amountPut}(lockTime);

        // Read after Put values
        uint after_contract_balance = address(c).balance;
        (uint after_unlockTime, uint after_recorded_balance) = c.Acc(address(this));

        // Now attempt Collect and observe whether it reverts
        bool collect_reverted;
        try c.Collect{value: 0}(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // Read final observed values after Collect attempt
        uint final_contract_balance = address(c).balance;
        (uint final_unlockTime, uint final_recorded_balance) = c.Acc(address(this));

        // Compute deltas safely without underflow using comparisons
        bool contract_increased_by_put = (after_contract_balance == before_contract_balance + amountPut);
        bool recorded_increased_by_put = (after_recorded_balance == before_recorded_balance + amountPut);

        // If Collect succeeded, the decrease in contract balance (if any) must be <= the recorded balance before Collect (after_put recorded)
        bool collect_decrease_ok;
        if (collect_reverted) {
            collect_decrease_ok = true;
        } else {
            if (after_contract_balance >= final_contract_balance) {
                uint contract_decrease = after_contract_balance - final_contract_balance;
                collect_decrease_ok = (contract_decrease <= after_recorded_balance);
            } else {
                // contract balance increased after Collect (e.g., receives funds); that's allowed
                collect_decrease_ok = true;
            }
        }

        // Final general assertion: Put must have increased both the contract's ETH and the recorded balance by exactly amountPut,
        // and if Collect succeeded it cannot withdraw more ETH than the recorded balance that existed just before the Collect.
        assert(contract_increased_by_put && recorded_increased_by_put && collect_decrease_ok);
    }

    // allow receiving Ether so this test contract can fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt a Collect only (no Put), and assert properties about balances and successful transfer.
    // Inputs: collectAmt is the requested withdrawal amount. We require no Ether be sent to this run call.
    function run(uint collectAmt) public payable {
        require(msg.value == 0);

        // Observe recorded balance and contract balance before Collect
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint before_contract_balance = address(c).balance;

        // Call Collect and capture whether it reverted
        bool collect_reverted;
        try c.Collect{value:0}(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // Observe recorded balance and contract balance after Collect attempt
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint after_contract_balance = address(c).balance;

        // Rule: Collect (which we invoked without sending Ether) must not increase the recorded balance for this address
        bool recorded_not_increased = (after_balance <= before_balance);

        // If Collect succeeded (did not revert) then:
        // - the contract's ether balance must have decreased by at most before_balance (can't send more than recorded)
        // - the recorded balance must have decreased by at least the amount sent out (i.e., by <= before_balance and >= 0)
        // Since we cannot read the exact transferred amount, we express consistency:
        //   If contract balance decreased, that decrease is <= before_balance.
        bool contract_decrease_ok;
        if (after_contract_balance <= before_contract_balance) {
            uint contract_decrease = before_contract_balance - after_contract_balance;
            contract_decrease_ok = (contract_decrease <= before_balance);
        } else {
            // contract balance increased or unchanged: that's acceptable
            contract_decrease_ok = true;
        }

        // If Collect succeeded then the recorded balance should not be larger than before and the net reduction in recorded balance
        // cannot exceed the prior recorded balance.
        bool recorded_decrease_ok = (after_balance <= before_balance);

        // Final single assert combining the general rules:
        // 1) Recorded balance never increases due to our Collect call.
        // 2) If Collect succeeded then the observed contract decrease (if any) is no more than the recorded balance before Collect,
        //    and the recorded balance did not increase.
        assert(recorded_not_increased && (collect_reverted || (contract_decrease_ok && recorded_decrease_ok)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try performing a Put to ensure some balance maybe present, then attempt Collect(amount).
    // We take putAmount and collectAmt as parameters and send putAmount as Ether when calling Put.
    function run(uint putLock, uint putAmount, uint collectAmt) public payable {
        // ensure this test contract has enough ETH to fund the Put call
        require(address(this).balance >= putAmount);

        // Initial observation of recorded balance and contract balance
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint before_contract_balance = address(c).balance;

        // If putAmount > 0 perform Put to increase recorded balance and c's balance
        if (putAmount > 0) {
            c.Put{value: putAmount}(putLock);
        }

        // Observe recorded balance and contract balance after Put
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint mid_contract_balance = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool collect_reverted;
        try c.Collect{value:0}(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // Observe recorded balance and contract balance after Collect attempt
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint after_contract_balance = address(c).balance;

        // If Collect succeeded, then:
        //  - the recorded balance must have decreased by at least collectAmt (i.e., before change >= collectAmt)
        //  - the contract's Ether balance must have decreased by exactly the same amount
        // We express decrease in recorded balance as (mid_balance - after_balance) when mid_balance >= after_balance.

        bool succeeded_rule;
        if (!collect_reverted) {
            // recorded balance must not increase
            if (after_balance > mid_balance) {
                succeeded_rule = false;
            } else {
                uint rec_decrease = mid_balance - after_balance;
                uint contract_decrease = 0;
                if (after_contract_balance <= mid_contract_balance) {
                    contract_decrease = mid_contract_balance - after_contract_balance;
                } else {
                    // contract balance increased though Collect succeeded: invalid for our rule
                    succeeded_rule = false;
                    // assert below will catch this; but set dummy and skip further checks
                    rec_decrease; // no-op to avoid compiler warning
                    contract_decrease; // no-op
                    // combine to false
                    succeeded_rule = false;
                    // Final assert will see succeeded_rule
                    assert(succeeded_rule || collect_reverted);
                    return;
                }

                // recorded decrease must be >= collectAmt
                bool rec_at_least = (rec_decrease >= collectAmt);
                // contract decrease must equal recorded decrease
                bool contract_matches = (contract_decrease == rec_decrease);
                succeeded_rule = rec_at_least && contract_matches;
            }
        } else {
            // If Collect reverted we don't require the above; property vacuously holds
            succeeded_rule = true;
        }

        // Single assert as required: either Collect reverted OR the succeeded_rule holds.
        assert(collect_reverted || succeeded_rule);
    }

    // Allow receiving ETH so this contract can fund Put
    receive() external payable {}
}

contract InvMutTest {
    C c;
