    // We take putAmount to fund Put (may be zero), putLock for Put, and collectAmt to attempt Collect.
    function run(uint putLock, uint putAmount, uint collectAmt) public payable {
        require(address(this).balance >= putAmount);

        // observe before values
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint before_contract_balance = address(c).balance;

        // perform Put if requested (top-level statement)
        if (putAmount > 0) {
            c.Put{value: putAmount}(putLock);
        }

        // observe mid values
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint mid_contract_balance = address(c).balance;

        // Attempt Collect and record whether it reverted (top-level try)
        bool collect_reverted;
        try c.Collect{value:0}(collectAmt) {
            collect_reverted = false;
        } catch {
            collect_reverted = true;
        }

        // observe after values
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint after_contract_balance = address(c).balance;

        // Single general assertion:
        // Either Collect reverted, or (1) recorded balance did not increase, (2) recorded decrease >= collectAmt,
        // and (3) contract's balance decreased by exactly the same recorded decrease.
        uint rec_decrease;
        if (mid_balance >= after_balance) {
            rec_decrease = mid_balance - after_balance;
        } else {
            // If recorded balance increased, set rec_decrease to 0 to make the assertion fail when needed
            rec_decrease = 0;
        }
        uint contract_decrease;
        if (mid_contract_balance >= after_contract_balance) {
            contract_decrease = mid_contract_balance - after_contract_balance;
        } else {
            contract_decrease = 0;
        }

        assert(collect_reverted || (after_balance <= mid_balance && rec_decrease >= collectAmt && contract_decrease == rec_decrease));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be used as the property test
    // params: lock time to Put, amount to Put, amount to try Collect
    function run(uint _lockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this contract has enough Ether to send to c when calling Put
        require(address(this).balance >= putAmount);

        // Read initial observable state for msg.sender (this contract) in c
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put to deposit Ether into c for this holder
        c.Put{value: putAmount}(_lockTime);

        // Read state after Put
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // The holder's balance must have increased by putAmount and contract balance too
        // Now attempt Collect of collectAmount and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after Collect attempt
        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        // General invariant to assert (single assert):
        // If Collect did not revert, then:
        //  - the holder's recorded balance decreased by exactly collectAmount
        //  - the contract's Ether balance decreased by exactly collectAmount
        // If Collect reverted, balances did not decrease because Collect made no state change.
        assert(
            // successful collect case
            (!reverted && afterBal >= collectAmount && afterBal == beforeBal + putAmount && finalBal + collectAmount == afterBal && afterContractBal == beforeContractBal + putAmount && finalContractBal + collectAmount == afterContractBal)
            ||
            // reverted case: no change from after-Put state to final state
            (reverted && finalBal == afterBal && finalContractBal == afterContractBal)
        );
    }

    // allow receiving Ether for setup
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that once Initialized() has been successfully called, SetMinSum and SetLogFile cannot succeed.
    // Parameters:
    //  doInitFirst: if true, call Initialized() before trying SetMinSum/SetLogFile; otherwise call them first then Initialized().
    //  minVal: value passed to SetMinSum
    //  logAddr: address passed to SetLogFile
    function run(bool doInitFirst, uint minVal, address logAddr) public payable {
        // Read initial 'MinSum' to observe before-state (public getter)
        uint beforeMin = c.MinSum();

        bool setMinRevertedBefore;
        bool setLogRevertedBefore;
        bool initReverted;

        if (doInitFirst) {
            // try to initialize first
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }

            // Then attempt SetMinSum and SetLogFile
            try c.SetMinSum(minVal) {
                setMinRevertedBefore = false;
            } catch {
                setMinRevertedBefore = true;
            }

            try c.SetLogFile(logAddr) {
                setLogRevertedBefore = false;
            } catch {
                setLogRevertedBefore = true;
            }
        } else {
            // attempt SetMinSum and SetLogFile first
            try c.SetMinSum(minVal) {
                setMinRevertedBefore = false;
            } catch {
                setMinRevertedBefore = true;
            }

            try c.SetLogFile(logAddr) {
                setLogRevertedBefore = false;
            } catch {
                setLogRevertedBefore = true;
            }

            // then try to initialize
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        }

        // Read MinSum after operations
        uint afterMin = c.MinSum();

        // Single assert expressing the invariant:
        // If Initialized() succeeded (did not revert) at the time it was called, then any SetMinSum or SetLogFile attempted after that must have reverted (i.e., they could not succeed to change MinSum from its value at the time of the call).
        // We express this conservatively using observable MinSum and the revert flags we recorded.
        // Cases:
        // - If initReverted == false and doInitFirst == true: initialization happened before attempts, so both setMin and setLog must have reverted. (We cannot directly observe LogFile, so require the revert flags.)
        // - If initReverted == false and doInitFirst == false: initialization happened after attempts, so SetMinSum may have succeeded; in that case afterMin should equal minVal.
        // - If initReverted == true: initialization didn't happen; SetMinSum may or may not have succeeded depending on its own revert flag; ensure consistency between flag and observed MinSum when initialization didn't happen after.

        assert(
            // init succeeded when done first: then both sets must have reverted
            ((initReverted == false && doInitFirst == true && setMinRevertedBefore == true && setLogRevertedBefore == true)
            ||
            // init succeeded when done after attempts: then if SetMinSum did not revert, MinSum must equal minVal; if it reverted, MinSum unchanged from before
            (initReverted == false && doInitFirst == false && ((setMinRevertedBefore == false && afterMin == minVal) || (setMinRevertedBefore == true && afterMin == beforeMin)))
            ||
            // init reverted: then we require consistency that if SetMinSum did not revert, MinSum == minVal; else MinSum unchanged
            (initReverted == true && ((setMinRevertedBefore == false && afterMin == minVal) || (setMinRevertedBefore == true && afterMin == beforeMin)))
            )
        );
    }

    receive() external payable {}
}

