                setMinReverted = true;
            }

            // then call Initialized()
            try c.Initialized() {
                initReverted = false;
            } catch {
                initReverted = true;
            }
        }

        // observe MinSum after operations
        uint afterMin = c.MinSum();

        // Single assert expressing the invariant:
        // If Initialized() succeeded when called before SetMinSum (doInitFirst==true and initReverted==false), then SetMinSum attempted afterwards must have reverted (setMinReverted==true) and MinSum unchanged from before.
        // Otherwise, if SetMinSum succeeded (setMinReverted==false), then afterMin must equal minVal.
        assert(
            (
                (doInitFirst == true && initReverted == false) ?
                    (setMinReverted == true && afterMin == beforeMin)
                :
                    (setMinReverted == false ? afterMin == minVal : afterMin == beforeMin)
            )
        );
    }

    receive() external payable {}
}

