    // lockTime: lock time passed to Put
    // collectAmount: amount attempted to Collect
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for put");
        // Ensure contract is in uninitialized state so SetLogFile/MinSum etc won't block Put/Collect by reverts elsewhere.
        // Note: c was freshly deployed by the checker; we simply proceed.

        // Call Put to fund the holder (msg.sender will be this test contract) sending Ether
        c.Put{value: putAmount}(lockTime);

        // read holder balance and contract balance before Collect
        (uint beforeBalance,) = (c.Acc(address(this)).balance, c.Acc(address(this)).unlockTime);
        // The above direct access to mapping struct via getter isn't available; use the public mapping getter.
        uint holderBefore = c.Acc(address(this)).balance;
        uint contractBefore = address(c).balance;

        bool collectReverted;
        bool sendSucceeded;
        // Attempt Collect; it may revert. Wrap in try/catch and detect whether the low-level send inside succeeded.
        try c.Collect(collectAmount) {
            collectReverted = false;
            // If Collect did not revert, we consider the external send may still have failed (but in Collect the low-level call's success gate is inside the contract flow before state update)
            // We detect net effects by reading state and balances below.
        } catch {
            collectReverted = true;
        }

        uint holderAfter = c.Acc(address(this)).balance;
        uint contractAfter = address(c).balance;

        // If Collect did not revert and the contract balance decreased by collectAmount, then holder balance must have decreased by exactly collectAmount.
        // Also if Collect did not revert and holder balance was sufficient and unlock time passed, collect would have attempted the send; we check concrete observable relation:
        // CASE: Collect succeeded and contract balance decreased by collectAmount => holderBefore - holderAfter == collectAmount && contractBefore - contractAfter == collectAmount

        assert(
            collectReverted || (
                (contractBefore >= contractAfter && (contractBefore - contractAfter == collectAmount))
                ? (holderBefore >= holderAfter && (holderBefore - holderAfter == collectAmount))
                : true
            )
        );
    }

    // accept Ether for sending Put
    receive() external payable {}
}

